using System;using System.Linq;
namespace IdleIntelligence.Core
{
 [Serializable]public sealed class LocalEvent
 {
  public bool costsRecorded,durationRecorded;public double actualSeconds;public NumberData creditCost=ScientificNumber.Zero.ToData(),dataCost=ScientificNumber.Zero.ToData();public double at;public long run,axiom;public string type,job,context,campaign;public NumberData credits,data,compute,users,income,insight;public long gems;
  public LocalEvent Copy(){var n=(LocalEvent)MemberwiseClone();n.creditCost=ScientificNumber.FromData(creditCost).ToData();n.dataCost=ScientificNumber.FromData(dataCost).ToData();n.credits=ScientificNumber.FromData(credits).ToData();n.data=ScientificNumber.FromData(data).ToData();n.compute=ScientificNumber.FromData(compute).ToData();n.users=ScientificNumber.FromData(users).ToData();n.income=ScientificNumber.FromData(income).ToData();n.insight=ScientificNumber.FromData(insight).ToData();return n;}
 }
 [Serializable]public sealed class LocalJournal
 {
  public LocalDiagnostics diagnostics=new LocalDiagnostics();public LocalEvent[] challengeEvents=Array.Empty<LocalEvent>();public long droppedChallengeEvents;public LocalBalanceHistory history=new LocalBalanceHistory();public ReturnReceipt[] returns=Array.Empty<ReturnReceipt>();public double measuredTaps;public bool tapsRecorded;public int schema=1;public bool initialized,historicalAvailable;public double since;public long dropped;public LocalEvent[] recent=Array.Empty<LocalEvent>(),permanent=Array.Empty<LocalEvent>();
  public static LocalJournal New(double now,bool available)=>new LocalJournal{diagnostics=new LocalDiagnostics{since=now,historicalUnavailable=!available},history=new LocalBalanceHistory{measurementKnown=available,measuredSince=now},tapsRecorded=available,initialized=true,historicalAvailable=available,since=now};
  public LocalJournal Copy(bool deep=false){var n=(LocalJournal)MemberwiseClone();n.diagnostics=diagnostics.Copy();n.challengeEvents=deep?challengeEvents.Select(x=>x.Copy()).ToArray():(LocalEvent[])challengeEvents.Clone();n.history=history.Copy(deep);n.returns=deep?returns.Select(x=>x.Copy()).ToArray():(ReturnReceipt[])returns.Clone();n.recent=deep?recent.Select(e=>e.Copy()).ToArray():(LocalEvent[])recent.Clone();n.permanent=deep?permanent.Select(e=>e.Copy()).ToArray():(LocalEvent[])permanent.Clone();return n;}
  public static LocalJournal Restore(LocalJournal j){if(j.history==null)j.history=new LocalBalanceHistory();if(!j.history.hasCurrent)j.history.current=null;foreach(var r in j.history.runs.Concat(j.history.current==null?Array.Empty<BalanceRunRecord>():new[]{j.history.current}))if(!r.hasEnd)r.end=null;return j;}
  public bool Has(string type)=>recent.Concat(permanent).Any(e=>e.type==type);
  public static void Record(GameState s,string type,string job="",bool permanent=false,ScientificNumber creditCost=null,ScientificNumber dataCost=null,double duration=-1,long run=-1){var j=s.Journal;var e=new LocalEvent{costsRecorded=creditCost!=null||dataCost!=null,creditCost=(creditCost??ScientificNumber.Zero).ToData(),dataCost=(dataCost??ScientificNumber.Zero).ToData(),durationRecorded=duration>=0,actualSeconds=Math.Max(0,duration),at=s.SavedAt,run=run>=0?run:s.Prestige.resets,axiom=s.Meta.resets,type=type,job=job??"",context=ChallengeRules.Active(s)?"challenge":"main",campaign=s.Missions.campaign,credits=s.Credits.ToData(),data=s.Data.ToData(),compute=Game.Compute(s).ToData(),users=Game.Users(s).ToData(),income=Game.Income(s).ToData(),insight=ScientificNumber.FromData(s.Prestige.knowledge).ToData(),gems=s.Retention.gems};LocalBalanceHistory.Event(s,e);var list=(permanent?j.permanent:j.recent).Concat(new[]{e}).ToArray();j.dropped+=Math.Max(0,list.Length-(permanent?JournalCatalog.Permanent:JournalCatalog.Recent));list=list.Skip(Math.Max(0,list.Length-(permanent?JournalCatalog.Permanent:JournalCatalog.Recent))).ToArray();if(permanent)j.permanent=list;else j.recent=list;}
  public static void Validate(LocalJournal j){if(j==null||!j.initialized||j.schema!=1||!ScientificNumber.Finite(j.since)||j.since<0||!ScientificNumber.Finite(j.measuredTaps)||j.measuredTaps<0||j.dropped<0||j.recent==null||j.permanent==null||j.recent.Length>JournalCatalog.Recent||j.permanent.Length>JournalCatalog.Permanent)throw new FormatException("Invalid event journal");LocalDiagnostics.Validate(j.diagnostics);LocalBalanceHistory.Validate(j.history);if(j.returns==null||j.returns.Length>JournalCatalog.Recent)throw new FormatException("Invalid return history");foreach(var r in j.returns)ReturnReceipt.Validate(r);if(j.challengeEvents==null||j.challengeEvents.Length>JournalCatalog.Challenge||j.droppedChallengeEvents<0)throw new FormatException("Invalid challenge archive");foreach(var e in j.recent.Concat(j.permanent).Concat(j.challengeEvents)){if(e==null||string.IsNullOrEmpty(e.type)||e.type.Length>80||!ScientificNumber.Finite(e.at)||e.at<0||e.run<0||e.axiom<0||e.gems<0||!ScientificNumber.Finite(e.actualSeconds)||e.actualSeconds<0||!new[]{"main","challenge"}.Contains(e.context))throw new FormatException("Invalid event");foreach(var n in new[]{e.credits,e.data,e.compute,e.users,e.income,e.insight,e.creditCost,e.dataCost})ScientificNumber.FromData(n);}}
 }
}
